function normalizeText(s){return String(s||'').trim().toLowerCase().replace(/\s+/g,' ')}
function codeRaw(q){return NAME_TO_CODE[q.subject]||q.subject||''}
function mappedChapter(q){const s=codeRaw(q),m=TOPIC_MAP[s]||{};return String(m[q.topic]||q.chapter||1)}
function dedupeBank(raw){const seen=new Set(),out=[];for(const q of raw){const s=codeRaw(q),k=s+'|'+normalizeText(q.text);if(seen.has(k))continue;seen.add(k);out.push({...q,chapter:mappedChapter(q),rawChapter:q.chapter})}return out}
