function migrate(v){if(!v.answers)v.answers=[];if(!v.errors)v.errors=[];if(!v.reviewQueue)v.reviewQueue=[];if(!v.examReports)v.examReports=[];if(!v.progress)v.progress={};if(!v.history)v.history=[];if(!v.notes)v.notes={};if(!v.customQuestions)v.customQuestions=[];if(!v.settings)v.settings={};if(!v.settings.plan)v.settings.plan={start:'',exam:'',finalDays:20,hours:2,weekdays:[0,1,2,3,4,5,6]};if(!v.settings.plan.hours)v.settings.plan.hours=2;if(!Array.isArray(v.settings.plan.weekdays))v.settings.plan.weekdays=[0,1,2,3,4,5,6];if(!v.wind)v.wind={foundationReached:false,lessonPassed:false,product:'winds'};if(!v.wind.product)v.wind.product='winds';if(!v.modules)v.modules={flightPlan:false,weightBalance:false,radioNav:false,nightIls:false};if(v.modules.radioNav===undefined)v.modules.radioNav=false;if(v.modules.nightIls===undefined)v.modules.nightIls=false;if(!v.briefing)v.briefing={};if(!v.trainer)v.trainer={history:[]};if(!v.inva)v.inva={history:[]};if(!v.atc)v.atc={history:[]};if(!v.emergency)v.emergency={history:[]};if(!v.settings.ui)v.settings.ui={fontScale:1,displayName:PROFILE_NAME};if(!v.settings.ui.displayName)v.settings.ui.displayName=PROFILE_NAME;v.schema=15;return v}
