function codeOf(q){return NAME_TO_CODE[q.subject]||q.subject||''}
function supplementalPool(){let a=[];try{if(Array.isArray(window.SOURCE_QUESTIONS))a.push(...window.SOURCE_QUESTIONS);if(Array.isArray(window.BOOK_QUESTIONS))a.push(...window.BOOK_QUESTIONS);if(Array.isArray(window.BOOK_DERIVED_QUESTIONS))a.push(...window.BOOK_DERIVED_QUESTIONS);if(Array.isArray(window.BOOK_CALCULATION_QUESTIONS))a.push(...window.BOOK_CALCULATION_QUESTIONS);if(Array.isArray(window.EXTERNAL_QUESTIONS))a.push(...window.EXTERNAL_QUESTIONS);a.push(...RADIONAV_QUESTIONS,...NIGHT_ILS_QUESTIONS,...FPL_QUESTIONS.map(q=>({...q,subject:'Navegação',chapter:'11'})),...WB_QUESTIONS,...WIND_QUESTIONS,...VFR_QUESTIONS.map(q=>({...q,subject:'Navegação',chapter:'3'})))}catch(e){}return a} function questionFingerprint(q){let t=normalizeText(q.text),generic=t.length<45||/^(assinale|qual|quais|indique|marque)/.test(t);return t+(generic?'|'+(q.options||[]).map(normalizeText).sort().join('|'):'')} function pool(sub=null,ch=null){let out=[],seen=new Set();for(const q of DB.concat(supplementalPool(),state.customQuestions||[])){if((sub&&codeOf(q)!==sub)||(ch!==null&&String(q.chapter)!==String(ch)))continue;let k=questionFingerprint(q);if(seen.has(k))continue;seen.add(k);out.push(q)}return out}
function chapters(sub){
 const meta=CURRICULUM[sub]||[]; const counts=new Map(); pool(sub).forEach(q=>counts.set(String(q.chapter),(counts.get(String(q.chapter))||0)+1));
 return meta.map(x=>[x.id,x.title,counts.get(String(x.id))||0,!!x.extra]);
}
function chapterState(sub,ch){state.progress[sub]??={};state.progress[sub][ch]??={review:false,memory:false,validation:false,mastered:false,lastScore:0};return state.progress[sub][ch]}
function chapterIndex(sub,ch){return (CURRICULUM[sub]||[]).findIndex(x=>String(x.id)===String(ch))}
function hasChapterContent(sub,ch){return pool(sub,ch).length>0} function chapterUnlocked(sub,ch){let i=chapterIndex(sub,ch);if(i<=0)return true;let cur=CURRICULUM[sub][i];if(cur&&cur.extra){let prev=[...CURRICULUM[sub].slice(0,i)].reverse().find(x=>!x.extra&&hasChapterContent(sub,x.id));return !prev||!!chapterState(sub,prev.id).mastered}let prev=[...CURRICULUM[sub].slice(0,i)].reverse().find(x=>!x.extra&&hasChapterContent(sub,x.id));return !prev||!!chapterState(sub,prev.id).mastered}
function mastery(sub){let a=state.answers.filter(x=>!sub||x.subject===sub);return a.length?Math.round(100*a.filter(x=>x.correct).length/a.length):0}
function renderHome(){document.querySelector('#home h1').textContent='Bom dia, '+((state.settings.ui&&state.settings.ui.displayName)||PROFILE_NAME)+'!';document.getElementById('today').textContent=new Intl.DateTimeFormat('pt-PT',{weekday:'long',day:'2-digit',month:'long',year:'numeric'}).format(new Date());document.getElementById('gauges').innerHTML=Object.keys(SUBJECTS).map(s=>`<div class="gauge"><strong>${mastery(s)}%</strong><span>${s}</span></div>`).join('');renderPlannerSummary()}
function renderSubjects(){document.getElementById('subjectList').innerHTML=Object.entries(SUBJECTS).map(([s,n])=>`<div class="row" data-subject="${s}"><div class="grow"><b>${s} — ${n}</b><small>${pool(s).length} questões locais • ${chapters(s).length} grupos/capítulos</small></div><span class="pill">${mastery(s)}%</span></div>`).join('')}
function openSubject(s){currentSubject=s;document.getElementById('chapterTitle').textContent=`${s} — ${SUBJECTS[s]}`;let cs=chapters(s);document.getElementById('chapterList').innerHTML=cs.map(([c,t,n,extra])=>{let st=chapterState(s,c),un=chapterUnlocked(s,c);return `<div class="row ${un?'':'lockedRow'}" data-chapter="${c}"><div class="grow"><b>${extra?'★ Aula Extra':'Cap. '+c} — ${t}</b><small>${n?n+' questões-base únicas':'material específico ainda não indexado'} • ${sourceVerified(s,c)?'fonte identificada':'fonte primária pendente'} • ${n?(st.mastered?'DOMINADO 95%+':un?'disponível':'bloqueado até dominar o anterior'):'não bloqueia a progressão'}</small></div><span>${st.mastered?'✓':un?'›':'🔒'}</span></div>`}).join('');go('chapters')}
function phasePanel(sub,ch){if(!hasChapterContent(sub,ch))return '<div class="notice">Este capítulo ainda não possui material específico indexado nesta compilação. Ele é mostrado no currículo, mas não bloqueia o próximo conteúdo disponível.</div>';let st=chapterState(sub,ch),i=chapterIndex(sub,ch),needReview=i>0&&!CURRICULUM[sub][i]?.extra;let reviewBtn=needReview?`<button class="btn ${st.review?'secondary':''}" data-action="chapterReview">${st.review?'✓':'1.'} REVISÃO ANTERIOR — 50</button>`:'';let memEnabled=!needReview||st.review;let valEnabled=st.memory;return `<div class="studyBox phaseBox"><div class="eyebrow">PROTOCOLO 95+</div><h3>Progressão obrigatória</h3><div class="phaseBtns">${reviewBtn}<button class="btn ${memEnabled?'':'disabled'}" ${memEnabled?'data-action="chapterMemory"':'disabled'}>${st.memory?'✓':'2.'} MEMORIZAÇÃO — 50</button><button class="btn ${valEnabled?'':'disabled'}" ${valEnabled?'data-action="chapterValidation"':'disabled'}>${st.validation?'✓':'3.'} VALIDAÇÃO — 50</button></div><small class="muted">Aprovação: mínimo 95%. Em 50 questões, a aplicação exige 48/50 (96%) para não arredondar 47/50 para cima.</small></div>`}
function openChapter(c){currentChapter=String(c);if(!chapterUnlocked(currentSubject,currentChapter)){alert('Capítulo bloqueado: domine o capítulo anterior com 95%+.');return}let qs=pool(currentSubject,currentChapter),meta=(CURRICULUM[currentSubject]||[]).find(x=>String(x.id)===currentChapter),topics=[...new Set(qs.map(q=>q.topic).filter(Boolean))];if(currentSubject==='NAV'&&currentChapter==='10')state.modules.radioNav=true;if(currentSubject==='NAV'&&currentChapter==='X1')state.modules.nightIls=true;unlockRelated(currentSubject,topics,qs);let extras=relatedLessonCards(currentSubject,topics,qs);if(currentSubject==='NAV'&&currentChapter==='10')extras+=`<div class="studyBox specialLesson"><b>📡 Laboratório desbloqueado:</b> VOR • NDB/ADF • Interceptação de Radiais <button class="btn small" data-go="radionav">ABRIR</button></div>`;if(currentSubject==='NAV'&&currentChapter==='X1')extras+=`<div class="studyBox specialLesson"><b>🌙 Aula extra:</b> Navegação Noturna & Familiarização ILS <button class="btn small" data-go="nightils">ABRIR</button></div>`;save();document.getElementById('studyTitle').textContent=`${currentSubject} • ${currentChapter==='X1'?'Aula Extra':'Cap. '+c}`;document.getElementById('studyBody').innerHTML=`<div class="studyBox"><div class="eyebrow">CONTEÚDO INDEXADO</div><h3>${meta?.title||topics[0]||'Capítulo '+c}</h3><p class="muted">Banco deduplicado: ${qs.length} questões-base únicas neste capítulo. Fonte: ${sourceVerified(currentSubject,currentChapter)?'identificada no inventário do projeto':'primária ainda pendente de indexação completa'}. Sessões de 50 distribuem as questões-base antes de repetir variações e preservam o gabarito.</p></div>${phasePanel(currentSubject,currentChapter)}${extras}`;go('study')}
function startQuiz(items,title,meta={}){items=shuffle(items);if(!items.length){alert('Não há questões disponíveis para este treino.');return false}quiz={items,index:0,correct:0,answered:false,title,meta};document.getElementById('quizTitle').textContent=title;go('quiz');renderQuestion();return true}
function renderQuestion(){let q=quiz.items[quiz.index],banca=!!quiz.meta?.banca;quiz.answered=false;document.getElementById('quizCount').textContent=`Questão ${quiz.index+1} de ${quiz.items.length}`;document.getElementById('quizScore').textContent=banca?'Modo Banca • sem feedback':`Acertos: ${quiz.correct}`;document.getElementById('quizBar').style.width=`${100*quiz.index/quiz.items.length}%`;document.getElementById('qText').textContent=q.text;document.getElementById('options').innerHTML=q.options.map((o,i)=>`<button class="opt" data-option="${i}"><b>${'ABCD'[i]}.</b> ${o}</button>`).join('');document.getElementById('feedback').classList.add('hide');document.getElementById('nextBtn').classList.add('hide')}
function scheduleReview(q,ok){let key=q.variantOf||q.id,old=state.reviewQueue.find(x=>x.id===key),steps=[1,3,7,14],stage=ok?(old?.stage||0)+1:0,days=steps[Math.min(stage,steps.length-1)],due=new Date(Date.now()+days*86400000).toISOString();if(old)Object.assign(old,{topic:q.topic||'',subject:codeOf(q),chapter:String(q.chapter),stage,due,attempts:(old.attempts||0)+1});else state.reviewQueue.push({id:key,topic:q.topic||'',subject:codeOf(q),chapter:String(q.chapter),stage,due,attempts:1});if(ok&&stage>=steps.length)state.reviewQueue=state.reviewQueue.filter(x=>x.id!==key)}
function answer(i){if(!quiz||quiz.answered)return;quiz.answered=true;let q=quiz.items[quiz.index],ok=i===q.correctIndex,banca=!!quiz.meta?.banca;if(ok)quiz.correct++;state.answers.push({id:q.id,subject:codeOf(q),chapter:String(q.chapter),topic:q.topic||'',phase:quiz.meta?.phase||'',correct:ok,at:new Date().toISOString()});if(!ok)state.errors.push({id:q.variantOf||q.id,subject:codeOf(q),chapter:String(q.chapter),topic:q.topic||'',at:new Date().toISOString()});scheduleReview(q,ok);save();document.querySelectorAll('.opt').forEach((b,n)=>{b.disabled=true;if(banca&&n===i)b.classList.add('sel');else if(!banca&&n===q.correctIndex)b.classList.add('correct');else if(!banca&&n===i)b.classList.add('wrong')});let f=document.getElementById('feedback');if(!banca){f.textContent=(ok?'✓ Correto. ':'✗ Resposta incorreta. ')+(q.explanation||'');f.classList.remove('hide')}let next=document.getElementById('nextBtn');next.textContent=banca?'GUARDAR E AVANÇAR →':'PRÓXIMA →';next.classList.remove('hide')}
function nextQuestion(){if(quiz.index+1>=quiz.items.length){let pct=100*quiz.correct/quiz.items.length,display=Math.round(pct),passed=pct>=95;state.history.push({title:quiz.title,score:display,count:quiz.items.length,passed,phase:quiz.meta?.phase||'',subject:quiz.meta?.subject||'',chapter:quiz.meta?.chapter||'',at:new Date().toISOString()});if(quiz.meta?.banca){let by={};quiz.items.forEach((q,i)=>{let s=codeOf(q);by[s]??={n:0,ok:0};by[s].n++;if((state.answers||[]).slice(-quiz.items.length)[i]?.correct)by[s].ok++});state.examReports.unshift({at:new Date().toISOString(),score:display,correct:quiz.correct,count:quiz.items.length,passed,by});state.examReports=state.examReports.slice(0,12)}if(quiz.meta?.phase&&quiz.meta?.subject&&quiz.meta?.chapter){let st=chapterState(quiz.meta.subject,quiz.meta.chapter);st.lastScore=display;if(passed){st[quiz.meta.phase]=true;if(quiz.meta.phase==='validation'){st.mastered=true;st.validation=true}}}save();if(quiz.meta?.banca){go('examreport');return}alert(`Treino concluído: ${display}% (${quiz.correct}/${quiz.items.length}) — ${passed?'APROVADO 95%+':'REPETIR: mínimo 95%'}`);if(quiz.meta?.subject){currentSubject=quiz.meta.subject;currentChapter=quiz.meta.chapter;openChapter(currentChapter)}else go('progress');return}quiz.index++;renderQuestion()}
function permuteQuestion(q,tag,idx){let opts=q.options.map((o,i)=>({o,i})),rot=(idx+tag.length)%opts.length;opts=opts.slice(rot).concat(opts.slice(0,rot));if(idx%2)opts.reverse();let ci=opts.findIndex(x=>x.i===q.correctIndex);let prefix=tag==='validation'?['Analise a situação e assinale a alternativa correta:','Em uma verificação de conhecimento, considere:','Aplicando o conceito estudado:'][idx%3]:tag==='review'?['Revisão:','Recupere o conceito anterior:','Antes de avançar, responda:'][idx%3]:['Memorização:','Consolide o conceito:','Recorde:'][idx%3];return {...q,id:`${q.id}-${tag}-${idx}`,text:`${prefix} ${q.text}`,options:opts.map(x=>x.o),correctIndex:ci,variantOf:q.id}}
function buildSession(sub,ch,n,phase){let base=pool(sub,ch);if(!base.length){if(sub==='NAV'&&ch==='10')base=RADIONAV_QUESTIONS;if(sub==='NAV'&&ch==='X1')base=NIGHT_ILS_QUESTIONS}if(!base.length)return[];let out=[],round=0;while(out.length<n){let block=shuffle(base);for(let q of block){if(out.length>=n)break;out.push(permuteQuestion(q,phase,out.length+round*7))}round++}return out}
function previousChapter(sub,ch){let i=chapterIndex(sub,ch);return i>0?CURRICULUM[sub][i-1]?.id:null}
function chapterReview(){let p=previousChapter(currentSubject,currentChapter),a=p?buildSession(currentSubject,p,50,'review'):[];if(!a.length)return alert('Sem banco anterior suficiente para revisão.');startQuiz(a,`${currentSubject} • Revisão antes do Cap. ${currentChapter}`,{phase:'review',subject:currentSubject,chapter:currentChapter})}
function chapterMemory(){let a=buildSession(currentSubject,currentChapter,50,'memory');if(!a.length)return alert('Este capítulo ainda não possui banco de treino.');startQuiz(a,`${currentSubject} ${currentChapter} • Memorização 50`,{phase:'memory',subject:currentSubject,chapter:currentChapter})}
function chapterValidation(){let a=buildSession(currentSubject,currentChapter,50,'validation');if(!a.length)return alert('Este capítulo ainda não possui banco de validação.');startQuiz(a,`${currentSubject} ${currentChapter} • Validação 50`,{phase:'validation',subject:currentSubject,chapter:currentChapter})}
function mixed(n){let arr=[];for(const s of Object.keys(SUBJECTS))arr.push(...shuffle(pool(s)).slice(0,Math.ceil(n/5)));return shuffle(arr).slice(0,n)}
function bancaItems(){let a=[];Object.keys(SUBJECTS).forEach(s=>a.push(...shuffle(pool(s)).slice(0,20)));return a.map((q,i)=>permuteQuestion(q,'validation',i+33))}
function dueItems(){let now=Date.now(),ids=new Set(state.reviewQueue.filter(x=>Date.parse(x.due)<=now).map(x=>x.id)),a=pool().filter(q=>ids.has(q.id)||ids.has(q.variantOf));return shuffle(a).slice(0,50)}
function startBanca(){let a=bancaItems();if(a.length<100)return alert('Banco ainda insuficiente para a prova completa.');startQuiz(a,'Modo Banca ANAC • 100 questões',{banca:true})}
function startDue(){let a=dueItems();if(!a.length)return alert('Não há revisões vencidas. Continue a estudar; os erros e conceitos recentes entrarão na fila automaticamente.');startQuiz(a,'Revisão espaçada • conceitos vencidos',{retention:true})}
function startSim(kind){if(kind==='mixed')startQuiz(mixed(20),'Simulado misto');if(kind==='full'){let a=[];Object.keys(SUBJECTS).forEach(s=>a.push(...shuffle(pool(s)).slice(0,20)));startQuiz(a,'Prova completa PPA')}if(kind==='banca')startBanca();if(kind==='due')startDue();if(kind==='errors'){let ids=new Set(state.errors.map(e=>e.id)),a=pool().filter(q=>ids.has(q.id)||ids.has(q.variantOf));startQuiz(a.length?a:mixed(20),'Recuperação de erros')}}
function renderBanca(){let due=dueItems(),e=document.getElementById('dueSummary'),t=document.getElementById('dueTitle');if(e)e.textContent=due.length?`${due.length} conceito(s) vencido(s) para recuperação agora.`:'Nenhuma revisão vencida agora. A fila será criada pelas respostas e erros de treino.';if(t)t.textContent=`Revisões de hoje • ${due.length}`}
function renderExamReport(){let e=document.getElementById('examReportBody'),r=state.examReports?.[0];if(!r){e.innerHTML='<div class="card"><p>Ainda não existe uma prova em Modo Banca.</p></div>';return}let rows=Object.entries(r.by).map(([s,x])=>{let p=Math.round(100*x.ok/x.n);return `<div class="notice ${p>=95?'ok':''}"><b>${s}</b> — ${p}% (${x.ok}/${x.n}) ${p<90?'• PRIORIDADE: recuperação dirigida':''}</div>`}).join('');e.innerHTML=`<div class="card"><div class="metric">${r.score}%</div><h3>${r.passed?'Meta 95%+ atingida':'Meta ainda não atingida'}</h3><p>${r.correct}/${r.count} corretas • ${new Date(r.at).toLocaleString('pt-PT')}</p><button class="btn wide" data-action="startDue">INICIAR RECUPERAÇÃO PROGRAMADA</button></div><div class="card" style="margin-top:10px"><h3>Resultado por matéria</h3>${rows}</div><div class="notice" style="margin-top:10px">Os erros desta prova já foram inseridos na fila de revisão de 1, 3, 7 e 14 dias. Para a meta 95+, repita o Modo Banca depois de tratar as matérias abaixo de 90%.</div>`}
function renderProgress(){let a=state.answers,c=a.filter(x=>x.correct).length,p=a.length?Math.round(100*c/a.length):0;document.getElementById('mastery').textContent=p+'%';document.getElementById('stats').innerHTML=`<p>Questões respondidas: <b>${a.length}</b></p><p>Corretas: <b>${c}</b></p><p>Erros registados: <b>${state.errors.length}</b></p><p>Simulados concluídos: <b>${state.history.length}</b></p>`;renderHome()}
function renderAI(){let s=document.getElementById('aiSubject');s.innerHTML=Object.entries(SUBJECTS).map(([k,v])=>`<option value="${k}">${k} — ${v}</option>`).join('');s.value=currentSubject;updateAIChapters()}
function updateAIChapters(){let s=document.getElementById('aiSubject').value,c=document.getElementById('aiChapter');c.innerHTML=chapters(s).map(([id,t])=>`<option value="${id}">${id==='X1'?'Extra':'Cap. '+id} — ${t}</option>`).join('')}
function generateQuestions(){let s=document.getElementById('aiSubject').value,c=document.getElementById('aiChapter').value,n=+document.getElementById('aiQty').value,level=document.getElementById('aiLevel').value;let a=buildSession(s,c,n,level==='Memorização'?'memory':'validation');document.getElementById('aiMsg').textContent=`Gerador local adaptativo: ${a.length} questões preparadas em nível ${level}. Questões OpenAI realmente inéditas continuam a exigir endpoint seguro online.`;if(a.length)startQuiz(a,`Treino adaptativo • ${s} ${c} • ${level}`)}
function net(){let el=document.getElementById('net'),on=navigator.onLine;el.textContent=on?'● ONLINE':'✈ OFFLINE';el.className='status '+(on?'online':'offline')}
async function weather(){
  const icao=document.getElementById('icao').value.trim().toUpperCase();
  if(!/^[A-Z]{4}$/.test(icao))return wx('ICAO inválido.','—',false);
  if(wxTab==='products'){document.getElementById('wxProducts').classList.remove('hide');return wx('Produtos oficiais disponíveis nos atalhos abaixo.','Selecione uma fonte oficial.',navigator.onLine)}
  if(wxTab==='sigmet'){document.getElementById('wxProducts').classList.remove('hide');return wx('SIGMET: consulta oficial online disponível abaixo.','Para evitar apresentar um aviso fora da FIR/validade correta, esta versão abre a fonte oficial; o cache integrado de SIGMET mundial permanece pendente de validação.',false)}
  const file=wxTab==='taf'?'tafs.json':'metars.json'; const label=wxTab==='taf'?'TAF':'METAR';
  const url=`./weather/${file}?v=${Date.now()}`;
  try{
    const r=await fetch(url,{cache:'no-store'}); if(!r.ok)throw new Error('feed HTTP '+r.status); const feed=await r.json(); if(window.PPAOfflineSync)await PPAOfflineSync.storeWeatherFeed(wxTab,feed).catch(()=>{});
    const dict=wxTab==='taf'?(feed.stations||feed.tafs||{}):(feed.stations||{}); const item=dict[icao]; if(!item||!(item.raw||item.rawTAF))throw new Error(`Sem ${label} recente para ${icao}`);
    const raw=item.raw||item.rawTAF, generated=feed.generatedAt||null, age=generated?(Date.now()-Date.parse(generated)):Infinity;
    const productTime=item.observationTime||item.issueTime||'', productAge=productTime?(Date.now()-Date.parse(productTime)):Infinity;
    const limit=wxTab==='taf'?30:20, productLimit=wxTab==='taf'?12*60:120;
    const feedFresh=Number.isFinite(age)&&age>=0&&age<=limit*60*1000, productFresh=Number.isFinite(productAge)&&productAge>=0&&productAge<=productLimit*60*1000, fresh=feedFresh&&productFresh;
    const obj={icao,raw,observationTime:productTime,feedGeneratedAt:generated,fetchedAt:new Date().toISOString(),type:label};
    localStorage.setItem(`ppa95_wx_${wxTab}_${icao}`,JSON.stringify(obj)); if(window.PPAOfflineSync)await PPAOfflineSync.storeWeatherProduct(wxTab,icao,feed,item).catch(()=>{}); wx(`${fresh?'● ATUALIZADO':'⚠ FEED ATRASADO'} • ${label} ${icao}`,raw,fresh,obj.fetchedAt,obj.observationTime,generated);
  }catch(e){const c=localStorage.getItem(`ppa95_wx_${wxTab}_${icao}`);if(c){const o=JSON.parse(c);wx(`✈ CACHE • ${o.type||label} ${icao} • não é dado atual`,o.raw,false,o.fetchedAt,o.observationTime,o.feedGeneratedAt)}else if(window.PPAOfflineDB){const r=await PPAOfflineDB.get(`wx:${wxTab}:${icao}`).catch(()=>null);if(r?.blob){const o=JSON.parse(await r.blob.text());wx(`✈ OFFLINE • ÚLTIMO BAIXADO • ${label} ${icao}`,o.raw||o.rawTAF||'—',false,r.updatedAt,o.productTime||o.observationTime||o.issueTime,o.feedGeneratedAt)}else wx(`SEM DADOS • ${label} indisponível e sem cache.`,String(e.message||e),false)}else wx(`SEM DADOS • ${label} indisponível e sem cache.`,String(e.message||e),false)}
}
function selectWxTab(tab){wxTab=tab;document.querySelectorAll('[data-wx-tab]').forEach(b=>{b.classList.toggle('secondary',b.dataset.wxTab!==tab)});document.getElementById('wxProducts').classList.toggle('hide',!['sigmet','products'].includes(tab));document.getElementById('wxState').textContent=`${tab.toUpperCase()} selecionado.`;document.getElementById('wxRaw').textContent='—'}

function wx(msg,raw,live,ts,obs,feedTs){
  const e=document.getElementById('wxState');e.textContent=msg;e.className='notice '+(live?'ok':'');
  document.getElementById('wxRaw').textContent=raw;
  const details=[];
  if(obs)details.push('Hora do produto: '+obs);
  if(feedTs)details.push('Feed: '+new Date(feedTs).toLocaleString('pt-PT'));
  details.push('Consulta: '+(ts?new Date(ts).toLocaleString('pt-PT'):'—'));
  document.getElementById('wxFetched').textContent=details.join(' • ');
  document.getElementById('wxMode').textContent='Estado: '+(live?'ATUALIZADO':'CACHE/OFFLINE');
}

async function renderOfflineCenter(){
  const msg=document.getElementById('offlineSyncMsg'); if(!window.PPAOfflineSync||!window.PPAOfflineDB){if(msg)msg.textContent='Motor offline indisponível.';return}
  try{const s=await PPAOfflineSync.status(),feeds=s.rows.filter(r=>r.kind==='weather-feed');document.getElementById('offlineProducts').textContent=s.stats.count;document.getElementById('offlineCharts').textContent=s.charts.length;document.getElementById('offlineWx').textContent=s.weather.length+feeds.length;document.getElementById('offlineBytes').textContent=PPAOfflineSync.fmtBytes(s.stats.bytes);document.getElementById('offlineCatalog').textContent=(s.catalog.entries||[]).length;
    document.getElementById('offlineItems').innerHTML=s.rows.length?s.rows.sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).slice(0,80).map(r=>`<div class="row"><div class="grow"><b>${r.meta?.name||r.meta?.icao||r.key}</b><small>${r.kind.toUpperCase()} • ${r.meta?.amdt||r.meta?.productTime||r.meta?.feedGeneratedAt||'versão local'} • ${new Date(r.updatedAt).toLocaleString('pt-PT')}</small></div><button class="btn secondary small" data-action="openOfflineItem" data-offline-key="${r.key}">ABRIR OFFLINE</button></div>`).join(''):'<div class="notice">Ainda não há produtos baixados neste dispositivo.</div>';
    if(msg)msg.textContent=`Banco local: ${s.stats.count} produto(s), incluindo ${feeds.length} feed(s) METAR/TAF completo(s). Catálogo oficial carregado: ${(s.catalog.entries||[]).length} carta(s).`;
  }catch(e){if(msg)msg.textContent='Não foi possível ler o banco offline: '+e.message}
}
async function openOfflineItem(){let key=window.__ppaOfflineOpenKey;if(!key)return;let url=await PPAOfflineSync.objectUrl(key);if(!url)return alert('O ficheiro não existe na base local.');let w=window.open(url,'_blank');if(!w)location.href=url;setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function requestPersistentStorage(){const e=document.getElementById('offlineSyncMsg');try{const r=await PPAOfflineSync.persistent();e.textContent=!r.supported?'Este navegador não expõe Storage Persistence.':r.granted?'Armazenamento persistente concedido pelo navegador.':'O navegador não concedeu armazenamento persistente; mantenha backups.'}catch(err){e.textContent='Persistência: '+err.message}}
async function syncOfflineAll(){const e=document.getElementById('offlineSyncMsg');e.textContent='Sincronizando…';try{await requestPersistentStorage();const report=await PPAOfflineSync.syncAll({onProgress:t=>e.textContent=t});const failed=report.weather.fail.length+report.charts.fail.length;e.textContent=`Sincronização concluída • feeds METAR/TAF completos: ${report.weather.feeds||0} • produtos METEO: ${report.weather.ok} • cartas atualizadas: ${report.charts.ok} • já atuais: ${report.charts.skipped||0} • retiradas: ${report.charts.removed||0} • falhas: ${failed}. Atualização substitui a versão local somente após download íntegro; em falha, a versão anterior é mantida.`;await renderOfflineCenter()}catch(err){e.textContent='Sincronização interrompida: '+err.message+' • versões anteriores preservadas.'}}
function renderFlight(){document.getElementById('offlineCount').textContent=pool().length;document.getElementById('offlineChecklist').innerHTML=['Interface da aplicação','Banco local de questões','Gabaritos e explicações','Progresso e erros','Simulados','Calendário e plano','Links de apoio guardados','METAR em cache quando já consultado'].map(x=>`<p>✓ ${x}</p>`).join('')}
async function prepareFlight(){const assets=['./','./index.html','./app.css','./app.js','./offline_db.js','./sync_manager.js','./offline/catalog.json','./data.js','./jorge_lessons.js','./book_bank.js','./source_grounded.js','./external_bank.js','./source_catalog.json','./manifest.json','./books/REG_Regulamentos_VFR_IFR.pdf','./books/MET_Meteorologia.pdf','./books/NAV_Navegacao_Visual.pdf','./books/TV_Teoria_de_Voo.pdf','./books/CT_Conhecimentos_Tecnicos.pdf','./icon.png','./weather/winds_latest.png','./weather/temperature_latest.png','./weather/clouds_latest.png','./weather/visibility_latest.png','./weather/storms_latest.png','./weather/weather_products.json','./weather/metars.json','./weather/tafs.json'];let cached=0,failed=[];if('caches'in window){let c=await caches.open('ppa95-flightpack-v18');for(const u of assets){try{let r=await fetch(u,{cache:'reload'});if(!r.ok)throw Error(String(r.status));await c.put(u,r.clone());cached++}catch(e){let old=await caches.match(u);if(old)cached++;else failed.push(u)}}}else cached=assets.length;localStorage.setItem('ppa95_flight_ready',new Date().toISOString());let e=document.getElementById('flightMsg');e.textContent=`FLIGHT PACK • ${cached}/${assets.length} recursos verificados • ${pool().length} questões locais incluindo banco dos 5 livros • ${failed.length?'faltam: '+failed.join(', '):'READY OFFLINE'}`;e.classList.remove('hide')}
async function getAllMaterials(){try{let db=await openDB(),tx=db.transaction('materials','readonly'),req=tx.objectStore('materials').getAll();return await new Promise((res,rej)=>{req.onsuccess=()=>res(req.result||[]);req.onerror=()=>rej(req.error)})}catch(e){return []}}
async function blobToDataURL(blob){let ab=await blob.arrayBuffer(),bytes=new Uint8Array(ab),bin='';for(let i=0;i<bytes.length;i+=0x8000)bin+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return `data:${blob.type||'application/octet-stream'};base64,${btoa(bin)}`}
function dataURLToBlob(s){let [h,b]=s.split(','),mime=(h.match(/data:([^;]+)/)||[])[1]||'application/octet-stream',bin=atob(b),a=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)a[i]=bin.charCodeAt(i);return new Blob([a],{type:mime})}
async function exportBackup(){let mats=await getAllMaterials(),materials=[];for(const m of mats)materials.push({...m,blob:undefined,data:await blobToDataURL(m.blob)});let payload={product:'PPA ANAC 95+',schema:14,exportedAt:new Date().toISOString(),state,materials};let blob=new Blob([JSON.stringify(payload)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`PPA95_Backup_${new Date().toISOString().slice(0,10)}.ppa`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);msgBackup(`Backup exportado: progresso + ${materials.length} material(is) local(is).`)}
function msgBackup(t){let e=document.getElementById('backupMsg');e.textContent=t;e.classList.remove('hide')}
async function importBackup(file){try{let x=JSON.parse(await file.text());if(x.product!=='PPA ANAC 95+'||!x.state)throw new Error('Backup incompatível ou inválido');let old=JSON.stringify(state);try{state=migrate(x.state);save();localStorage.setItem('ppa95_last_preimport',old);if(Array.isArray(x.materials)&&x.materials.length){let db=await openDB(),tx=db.transaction('materials','readwrite'),st=tx.objectStore('materials');for(const m of x.materials)if(m.data)st.put({id:m.id||crypto.randomUUID(),name:m.name||'material',type:m.type||'',size:m.size||0,addedAt:m.addedAt||new Date().toISOString(),blob:dataURLToBlob(m.data)});await new Promise((r,j)=>{tx.oncomplete=r;tx.onerror=()=>j(tx.error)})}}catch(e){state=JSON.parse(old);throw e}msgBackup(`Backup restaurado: ${state.answers.length} respostas, ${state.errors.length} erros, ${state.history.length} simulados e ${(x.materials||[]).length} material(is).`)}catch(e){msgBackup('Não foi possível restaurar: '+e.message)}}
function openDB(){return new Promise((res,rej)=>{let r=indexedDB.open('ppa95_files',1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('materials'))r.result.createObjectStore('materials',{keyPath:'id'})};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function saveMaterial(){let fs=[...document.getElementById('materialFile').files];if(!fs.length)return document.getElementById('materialMsg').textContent='Selecione pelo menos um ficheiro.';try{let db=await openDB(),tx=db.transaction('materials','readwrite'),st=tx.objectStore('materials');for(const f of fs)st.put({id:crypto.randomUUID(),name:f.name,type:f.type,size:f.size,addedAt:new Date().toISOString(),blob:f});await new Promise((r,j)=>{tx.oncomplete=r;tx.onerror=()=>j(tx.error)});document.getElementById('materialMsg').textContent=`${fs.length} ficheiro(s) guardado(s) localmente.`}catch(e){document.getElementById('materialMsg').textContent='Erro ao guardar: '+e.message}}
function mission(){let plan=generatePlan(),m=plan[0]?.text||'';let hit=m.match(/^(REG|MET|NAV|TV|CT) • Cap\. ([^ ]+)/);if(hit){currentSubject=hit[1];currentChapter=hit[2];openChapter(currentChapter);return}let weak=Object.keys(SUBJECTS).sort((a,b)=>mastery(a)-mastery(b))[0];startQuiz(shuffle(pool(weak)).slice(0,20),`Missão de hoje • ${weak}`)}
