function dateOnly(s){return s?new Date(s+'T12:00:00'):null}
function daysBetween(a,b){return Math.max(0,Math.floor((b-a)/86400000))}
function generatePlan(){let p=state.settings.plan,start=dateOnly(p.start),exam=dateOnly(p.exam),finalDays=+p.finalDays||20;if(!start||!exam||exam<=start)return [];let today=new Date();today.setHours(12,0,0,0);let studyEnd=new Date(exam.getTime()-finalDays*86400000),seq=[],subjects=Object.keys(SUBJECTS),d=new Date(Math.max(start.getTime(),today.getTime())),idx=0,week=new Set(p.weekdays||[0,1,2,3,4,5,6]),hours=+p.hours||2;let pending={};for(const s of subjects)pending[s]=(CURRICULUM[s]||[]).filter(x=>!x.extra&&hasChapterContent(s,x.id)&&!chapterState(s,x.id).mastered);while(d<exam&&seq.length<60){if(!week.has(d.getDay())){d=new Date(d.getTime()+86400000);continue}let ds=d.toISOString().slice(0,10);if(d>=studyEnd){seq.push({date:ds,text:'Reta final • simulado misto + recuperação de erros'});}else{let tries=0,s;do{s=subjects[idx%subjects.length];idx++;tries++}while(tries<subjects.length&&!pending[s].length);let c=pending[s]?.shift();seq.push({date:ds,text:c?`${s} • Cap. ${c.id} • ${c.title} • protocolo 95% • ${hours}h disponíveis`:'Revisão geral • erros + simulados'});}d=new Date(d.getTime()+86400000)}return seq}
function renderPlanner(){let p=state.settings.plan;document.getElementById('planStart').value=p.start||'';document.getElementById('planExam').value=p.exam||'';document.getElementById('planFinalDays').value=p.finalDays||20;document.getElementById('planHours').value=p.hours||2;document.querySelectorAll('[data-weekday]').forEach(x=>x.checked=(p.weekdays||[0,1,2,3,4,5,6]).includes(+x.dataset.weekday));let a=generatePlan();document.getElementById('planToday').textContent=a[0]?a[0].text:'Configure datas válidas para gerar o plano.';document.getElementById('planList').innerHTML=a.slice(0,14).map(x=>`<div class="row"><div class="grow"><b>${new Date(x.date+'T12:00:00').toLocaleDateString('pt-PT',{weekday:'short',day:'2-digit',month:'2-digit'})}</b><small>${x.text}</small></div></div>`).join('')}
function renderPlannerSummary(){let el=document.getElementById('missionText');if(!el)return;let a=generatePlan();el.textContent=a[0]?a[0].text:'Configure o Calendário & Plano para gerar a missão diária.'}
function savePlan(){let weekdays=[...document.querySelectorAll('[data-weekday]:checked')].map(x=>+x.dataset.weekday);if(!weekdays.length)return alert('Selecione pelo menos um dia da semana.');state.settings.plan={start:document.getElementById('planStart').value,exam:document.getElementById('planExam').value,finalDays:Math.max(1,+document.getElementById('planFinalDays').value||20),hours:Math.max(.5,+document.getElementById('planHours').value||2),weekdays};save();renderPlanner()}
function exportICS(){let a=generatePlan();if(!a.length){alert('Configure primeiro um plano válido.');return}let esc=s=>String(s).replace(/,/g,'\\,').replace(/;/g,'\\;').replace(/\n/g,'\\n');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//PPA ANAC 95+//PT'];for(const x of a){let d=x.date.replace(/-/g,'');lines.push('BEGIN:VEVENT',`DTSTART;VALUE=DATE:${d}`,`DTEND;VALUE=DATE:${d}`,`SUMMARY:${esc('PPA 95+ — '+x.text)}`,'END:VEVENT')}lines.push('END:VCALENDAR');let blob=new Blob([lines.join('\r\n')],{type:'text/calendar'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='PPA95_Plano_Estudos.ics';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}

