function validateFpl(){let v=id=>document.getElementById(id).value.trim().toUpperCase(),errs=[];let id=v('fplId'),rules=v('fplRules'),dep=v('fplDep'),time=v('fplTime'),dest=v('fplDest'),eet=v('fplEet'),end=v('fplEnd'),pob=v('fplPob');if(!/^[A-Z0-9]{2,7}$/.test(id))errs.push('Item 7: identificação inválida para este exercício.');if(!/^[IVYZ][GNSMX]$/.test(rules))errs.push('Item 8: use regra I/V/Y/Z + tipo de voo.');if(!/^[A-Z]{4}$/.test(dep))errs.push('Item 13: indicador de partida deve ter 4 letras no exemplo ICAO.');if(!/^([01]\d|2[0-3])[0-5]\d$/.test(time))errs.push('EOBT: use HHMM UTC.');if(!/^[A-Z]{4}$/.test(dest))errs.push('Item 16: destino deve ter 4 letras no exemplo ICAO.');if(!/^\d{4}$/.test(eet))errs.push('EET: use HHMM.');if(!/^\d{4}$/.test(end))errs.push('Autonomia: use HHMM.');if(!/^\d{1,3}$/.test(pob))errs.push('POB: informe um número.');let line=`(FPL-${id}-${rules}\n-${v('fplType')}\n-${v('fplEquip')}\n-${dep}${time}\n-${v('fplSpeed')}${v('fplLevel')} ${v('fplRoute')}\n-${dest}${eet} ${v('fplAlt')}\n-E/${end} P/${pob})`;document.getElementById('fplPreview').textContent=line;let r=document.getElementById('fplResult');r.textContent=errs.length?('Revise: '+errs.join(' ')):'✓ Estrutura didática coerente nos campos básicos verificados. Compare agora com o MCA 100-11 e com as exigências do voo real.';r.className='notice '+(errs.length?'':'ok')}
