function cgForwardLimit(w){if(w<=1350)return 31;return 31+(Math.min(w,1670)-1350)*(32.65-31)/(1670-1350)}
function calcWB(){if(!document.getElementById('wbEnvelope'))return;let items=[[num('wbEmptyW'),num('wbEmptyA')],[num('wbFuel')*6,42.2],[num('wbPilot')+num('wbPax'),39],[num('wbBag1'),64],[num('wbBag2'),84]],w=items.reduce((s,x)=>s+x[0],0),m=items.reduce((s,x)=>s+x[0]*x[1],0),cg=w?m/w:0,fwd=cgForwardLimit(w),ok=w<=1670&&w>=1000&&cg>=fwd&&cg<=36.5;let e=document.getElementById('wbResult');e.innerHTML=`Peso: <b>${w.toFixed(1)} lb</b> • Momento: <b>${(m/1000).toFixed(2)} mil lb·in</b> • CG: <b>${cg.toFixed(2)} in</b><br>${ok?'✓ Ponto dentro do envelope didático.':'⚠ Ponto FORA do envelope didático.'}`;e.className='notice '+(ok?'ok':'');drawWB(cg,w,ok)}
function drawWB(cg,w,ok){let s=document.getElementById('wbEnvelope'),X=x=>55+(x-30)/8*420,Y=y=>330-(y-1000)/750*280;let poly=[[31,1000],[31,1350],[32.65,1670],[36.5,1670],[36.5,1000]].map(p=>X(p[0])+','+Y(p[1])).join(' ');let grid='';for(let x=30;x<=38;x++)grid+=`<line x1="${X(x)}" y1="50" x2="${X(x)}" y2="330"/><text x="${X(x)}" y="352">${x}</text>`;for(let y=1000;y<=1750;y+=150)grid+=`<line x1="55" y1="${Y(y)}" x2="475" y2="${Y(y)}"/><text x="48" y="${Y(y)+4}" text-anchor="end">${y}</text>`;s.innerHTML=`<rect x="0" y="0" width="520" height="390" rx="16" fill="#061827"/><g class="wbgrid">${grid}</g><polygon points="${poly}" fill="rgba(53,223,136,.13)" stroke="#35df88" stroke-width="3"/><text x="260" y="25" class="wbtitle">C152 • ENVELOPE CG DE TREINO</text><text x="260" y="380" class="wblabel">CG (in atrás do datum)</text><text transform="translate(15 210) rotate(-90)" class="wblabel">Peso (lb)</text>${Number.isFinite(cg)&&w?`<circle cx="${X(cg)}" cy="${Y(w)}" r="8" fill="${ok?'#35df88':'#ff6678'}" stroke="#fff" stroke-width="2"/><text x="${Math.min(450,X(cg)+12)}" y="${Math.max(65,Y(w)-10)}" class="wbpoint">${cg.toFixed(2)} / ${w.toFixed(0)}</text>`:''}`}
