function bookPool(subject='ALL',mode='all'){
 let a=[];if(mode!=='derived')a.push(...(window.BOOK_QUESTIONS||[]));if(mode!=='direct')a.push(...(window.BOOK_DERIVED_QUESTIONS||[]));if(mode==='all')a.push(...(window.BOOK_CALCULATION_QUESTIONS||[]));
 if(subject!=='ALL')a=a.filter(q=>codeOf(q)===subject);return a;
}
function startBookSim(){let s=document.getElementById('bookSimSubject')?.value||'ALL',qty=document.getElementById('bookSimQty')?.value||'100',mode=document.getElementById('bookSimMode')?.value||'all',a=bookPool(s,mode),n=qty==='all'?a.length:Math.max(1,Math.min(+qty||100,a.length));startQuiz(shuffle(a).slice(0,n),`5 Livros • ${s==='ALL'?'Misto':s} • ${n} questões`,{phase:'books'})}
function startCalculationSim(){let a=(window.BOOK_CALCULATION_QUESTIONS||[]);if(!a.length)a=(window.BOOK_QUESTIONS||[]).filter(q=>q.isCalculation);startQuiz(shuffle(a).slice(0,Math.min(100,a.length)),`5 Livros • Cálculos com resolução • ${Math.min(100,a.length)} questões`,{phase:'calculations'})}
function renderBookStats(){let e=document.getElementById('bookStats');if(!e)return;let st=window.BOOK_BANK_STATS||{};e.innerHTML=`<div class="grid5"><div class="card"><div class="metric">${st.directUnique||0}</div><p>questões diretas únicas</p></div><div class="card"><div class="metric">${st.phraseDerived||0}</div><p>frase-a-frase</p></div><div class="card"><div class="metric">${st.calculationResolved||0}</div><p>cálculos com resolução</p></div><div class="card"><div class="metric">${st.duplicateMerges||0}</div><p>repetições fundidas</p></div><div class="card"><div class="metric">5</div><p>livros indexados</p></div></div>`}
let currentBookCode='REG';
function renderBooks(){let e=document.getElementById('bookCatalog');if(!e)return;if(ACTIVE_PROFILE!=='candido'){e.innerHTML='<div class="notice">Leitura e estudo dos cinco livros disponível somente no perfil Cândido.</div>';return}let cat=window.BOOK_CATALOG||{};e.innerHTML=Object.entries(cat).map(([k,b])=>`<div class="row"><div class="grow"><b>${k} — ${b.title}</b><small>${b.direct} questões diretas • ${b.derived} frase-a-frase</small></div><button class="btn small secondary" data-open-book="${k}">LER</button></div>`).join('');let saved=localStorage.getItem('ppa95_last_book_v15')||'REG';openBook(saved,false)}
function openBook(code,focus=true){if(ACTIVE_PROFILE!=='candido')return;let b=(window.BOOK_CATALOG||{})[code];if(!b)return;currentBookCode=code;localStorage.setItem('ppa95_last_book_v15',code);let page=+(localStorage.getItem('ppa95_book_page_'+code)||1);let t=document.getElementById('bookReaderTitle'),fr=document.getElementById('bookFrame'),pn=document.getElementById('bookPage'),ln=document.getElementById('bookOpenLink');if(t)t.textContent=code+' — '+b.title;if(pn)pn.value=page;if(ln)ln.href=b.file+'#page='+page;if(fr)fr.src=b.file+'#page='+page;if(focus)document.getElementById('bookReader')?.scrollIntoView({behavior:'smooth',block:'start'})}
function saveBookMarker(){if(ACTIVE_PROFILE!=='candido')return;let p=Math.max(1,+document.getElementById('bookPage').value||1);localStorage.setItem('ppa95_book_page_'+currentBookCode,p);openBook(currentBookCode,false);let e=document.getElementById('bookMarkerMsg');if(e){e.textContent='Marcador guardado na página '+p+' para '+currentBookCode+'.';e.classList.remove('hide')}}


let jorgeSubject='CT',jorgeLessonIndex=0,jorgePage=1;
function jorgeKey(suffix){return 'ppa95_jorge_study_'+suffix}
function renderJorgeStudy(){
 if(ACTIVE_PROFILE!=='jorge')return;
 const data=window.JORGE_STUDY||{}; if(!Object.keys(data).length)return;
 jorgeSubject=localStorage.getItem(jorgeKey('subject'))||'CT'; if(!data[jorgeSubject])jorgeSubject='CT';
 const tabs=document.getElementById('jorgeSubjectTabs');
 if(tabs)tabs.innerHTML=['CT','NAV','MET','TV','REG'].map(c=>`<button class="btn small ${c===jorgeSubject?'active':'secondary'}" data-jorge-subject="${c}">${c}</button>`).join('');
 renderJorgeLessons();
 let li=+(localStorage.getItem(jorgeKey('lesson_'+jorgeSubject))||0); if(li<0||li>=data[jorgeSubject].lessons.length)li=0; openJorgeLesson(li,false);
}
function renderJorgeLessons(){
 const b=(window.JORGE_STUDY||{})[jorgeSubject];if(!b)return;
 const title=document.getElementById('jorgeSubjectTitle'),eye=document.getElementById('jorgeSubjectEyebrow');if(title)title.textContent=jorgeSubject+' — '+b.title;if(eye)eye.textContent=`${b.lessons.length} LIÇÕES • ${b.pages} PÁGINAS`;
 const done=JSON.parse(localStorage.getItem(jorgeKey('done_'+jorgeSubject))||'[]');
 const list=document.getElementById('jorgeLessonList');if(!list)return;
 list.innerHTML=b.lessons.map((l,i)=>`<div class="row lessonRow ${i===jorgeLessonIndex?'active':''} ${done.includes(l.n)?'done':''}"><div class="grow"><b>${String(l.n).padStart(2,'0')}. ${l.title}</b><small>Páginas ${l.start}–${l.end}<span class="scopeTag">${l.scope}</span></small><div class="lessonProgress">${done.includes(l.n)?'Concluída':'Para estudar'}</div></div><button class="btn small secondary" data-jorge-lesson="${i}">LER</button></div>`).join('');
}
function openJorgeLesson(index,focus=true){
 if(ACTIVE_PROFILE!=='jorge')return;const b=(window.JORGE_STUDY||{})[jorgeSubject];if(!b)return;index=Math.max(0,Math.min(index,b.lessons.length-1));jorgeLessonIndex=index;const l=b.lessons[index];localStorage.setItem(jorgeKey('lesson_'+jorgeSubject),String(index));let saved=+(localStorage.getItem(jorgeKey('page_'+jorgeSubject+'_'+l.n))||l.start);jorgePage=Math.max(l.start,Math.min(saved,l.end));renderJorgeReader();renderJorgeLessons();if(focus)document.getElementById('jorgeReader')?.scrollIntoView({behavior:'smooth',block:'start'});
}
function renderJorgeReader(){
 const b=(window.JORGE_STUDY||{})[jorgeSubject],l=b?.lessons?.[jorgeLessonIndex];if(!b||!l)return;jorgePage=Math.max(l.start,Math.min(jorgePage,l.end));localStorage.setItem(jorgeKey('page_'+jorgeSubject+'_'+l.n),String(jorgePage));
 const t=document.getElementById('jorgeLessonTitle'),m=document.getElementById('jorgeLessonMeta'),now=document.getElementById('jorgePageNow'),range=document.getElementById('jorgePageRange'),inp=document.getElementById('jorgePageInput'),fr=document.getElementById('jorgeFrame');
 if(t)t.textContent=`${jorgeSubject} ${l.n} — ${l.title}`;if(m)m.textContent=`LIÇÃO ${l.n}/${b.lessons.length} • ${l.scope} • PÁGINAS ${l.start}–${l.end}`;if(now)now.textContent=jorgePage;if(range)range.textContent=`/ ${l.end}`;if(inp){inp.min=l.start;inp.max=l.end;inp.value=jorgePage}if(fr){let target=b.file+'#page='+jorgePage+'&zoom=page-width';if(fr.getAttribute('src')!==target)fr.src=target}
}
function jorgePrevPage(){const b=(window.JORGE_STUDY||{})[jorgeSubject],l=b?.lessons?.[jorgeLessonIndex];if(!l)return;if(jorgePage>l.start){jorgePage--;renderJorgeReader()}else if(jorgeLessonIndex>0){openJorgeLesson(jorgeLessonIndex-1,true);let prev=b.lessons[jorgeLessonIndex];jorgePage=prev.end;renderJorgeReader()}else jorgeStudyToast('Já está na primeira página da primeira lição.')}
function jorgeNextPage(){const b=(window.JORGE_STUDY||{})[jorgeSubject],l=b?.lessons?.[jorgeLessonIndex];if(!l)return;if(jorgePage<l.end){jorgePage++;renderJorgeReader()}else if(jorgeLessonIndex<b.lessons.length-1){openJorgeLesson(jorgeLessonIndex+1,true)}else jorgeStudyToast('Chegou ao fim desta matéria.')}
function jorgeGoPage(){const b=(window.JORGE_STUDY||{})[jorgeSubject],l=b?.lessons?.[jorgeLessonIndex];if(!l)return;let p=+document.getElementById('jorgePageInput')?.value||l.start;jorgePage=Math.max(l.start,Math.min(p,l.end));renderJorgeReader()}
function jorgeMarkDone(){const b=(window.JORGE_STUDY||{})[jorgeSubject],l=b?.lessons?.[jorgeLessonIndex];if(!l)return;let done=JSON.parse(localStorage.getItem(jorgeKey('done_'+jorgeSubject))||'[]');if(!done.includes(l.n))done.push(l.n);localStorage.setItem(jorgeKey('done_'+jorgeSubject),JSON.stringify(done));renderJorgeLessons();jorgeStudyToast(`Lição ${l.n} marcada como concluída.`)}
function jorgeBackToLessons(){document.querySelector('.lessonPane')?.scrollIntoView({behavior:'smooth',block:'start'})}
function jorgeStudyToast(msg){let e=document.getElementById('jorgeStudyMsg');if(e){e.textContent=msg;e.classList.remove('hide');setTimeout(()=>e.classList.add('hide'),2200)}}
function setJorgeSubject(code){if(ACTIVE_PROFILE!=='jorge'||!(window.JORGE_STUDY||{})[code])return;jorgeSubject=code;jorgeLessonIndex=+(localStorage.getItem(jorgeKey('lesson_'+code))||0);localStorage.setItem(jorgeKey('subject'),code);renderJorgeStudy()}

