function diagnosticResults(){let out=[],t=(name,fn)=>{try{out.push({name,ok:!!fn()})}catch(e){out.push({name,ok:false,detail:e.message})}};t('Banco bruto carregado',()=>RAW_DB.length===1240);t('Banco deduplicado 280',()=>DB.length===280);t('Sem duplicados exatos no banco-base',()=>new Set(DB.map(q=>codeOf(q)+'|'+normalizeText(q.text))).size===DB.length);t('Nenhuma questão-base permanece no capítulo 0',()=>DB.every(q=>String(q.chapter)!=='0'));t('Cinco matérias com conteúdo',()=>Object.keys(SUBJECTS).every(s=>pool(s).length>0));t('Sessão 50 Memorização',()=>buildSession('NAV','9',50,'memory').length===50);t('Sessão 50 Validação',()=>buildSession('NAV','9',50,'validation').length===50);t('Regra 95%: 47/50 reprova',()=>47/50*100<95);t('Regra 95%: 48/50 aprova',()=>48/50*100>=95);t('Prova completa 100',()=>bancaItems().length===100);t('Modo Banca sem feedback imediato',()=>startBanca.toString().includes('banca:true')&&answer.toString().includes('banca'));t('Retenção 1/3/7/14 dias',()=>scheduleReview.toString().includes('[1,3,7,14]'));t('Backup schema V15 + materiais',()=>fresh().schema===15&&typeof getAllMaterials==='function'&&typeof blobToDataURL==='function');t('METAR/TAF completo no banco',()=>typeof PPAOfflineSync.syncWeatherFeeds==='function'&&syncOfflineAll.toString().includes('feeds METAR/TAF completos'));t('Cartas com troca atómica',()=>PPAOfflineSync.syncChart.toString().includes('putAtomic'));t('Acesso direto offline',()=>typeof openOfflineItem==='function');t('Banco offline',()=>!!window.PPAOfflineDB&&typeof PPAOfflineDB.putAtomic==='function');t('Sincronização offline',()=>!!window.PPAOfflineSync&&typeof PPAOfflineSync.syncAll==='function'&&!!document.getElementById('offlinecenter'));t('Banco direto dos 5 livros',()=>Array.isArray(window.BOOK_QUESTIONS)&&window.BOOK_QUESTIONS.length===window.BOOK_BANK_STATS.directUnique);t('Gabaritos dos 5 livros conferidos',()=>window.BOOK_QUESTIONS.every(q=>Number.isInteger(q.correctIndex)&&q.correctIndex>=0&&q.correctIndex<4));t('Sem duplicados exatos no banco dos livros',()=>new Set(window.BOOK_QUESTIONS.map(q=>normalizeText(q.text)+'|'+q.options.map(normalizeText).sort().join('|'))).size===window.BOOK_QUESTIONS.length);t('Filtro global de repetição ativo',()=>{let a=pool();return new Set(a.map(questionFingerprint)).size===a.length});t('Banco frase-a-frase ativo',()=>Array.isArray(window.BOOK_DERIVED_QUESTIONS)&&window.BOOK_DERIVED_QUESTIONS.length>500);t('Cálculos com resolução passo a passo',()=>Array.isArray(window.BOOK_CALCULATION_QUESTIONS)&&window.BOOK_CALCULATION_QUESTIONS.length>=100&&window.BOOK_CALCULATION_QUESTIONS.every(q=>String(q.explanation).includes('Resolução:')));t('Bancos externos V17 carregados',()=>Array.isArray(window.EXTERNAL_QUESTIONS)&&window.EXTERNAL_QUESTIONS.length>=63&&window.EXTERNAL_QUESTIONS.every(q=>codeOf(q)==='TV'));t('Perfis separados',()=>K.includes('ppa95_state_v15_'));return out}
