async function loadWindMeta(force=false,product=activeWxProduct||state.wind.product||'winds'){let st=document.getElementById('windState'),up=document.getElementById('windUpdated'),img=document.getElementById('windChart');try{let r=await fetch('./weather/weather_products.json?v='+(force?Date.now():'0'),{cache:force?'no-store':'default'});if(!r.ok)throw Error('meta');let m=await r.json(),item=(m.products||{})[product]||{},ts=item.generatedAt||m.generatedAt,age=Date.now()-Date.parse(ts||'');let live=navigator.onLine&&Number.isFinite(age)&&age>=0&&age<4*3600000;st.textContent=live?'● ONLINE':'✈ CACHE';up.textContent='Captura: '+(ts?new Date(ts).toLocaleString('pt-PT'):'—');let src=document.getElementById('windSource');if(src)src.textContent='Fonte: '+(item.source||m.source||'—')+(item.coverage?' • '+item.coverage:'');img.style.display='block';let p=WX_PRODUCT_INFO[product];if(p&&(force||!img.src.includes(p.file)))img.src='./weather/'+p.file+'?v='+(force?Date.now():'0');localStorage.setItem('ppa95_weather_products',JSON.stringify(m))}catch(e){let c=localStorage.getItem('ppa95_weather_products'),m=c?JSON.parse(c):null,item=m&&m.products?m.products[product]:null,ts=item&&item.generatedAt;st.textContent='✈ CACHE';up.textContent=ts?'Última captura: '+new Date(ts).toLocaleString('pt-PT'):'Atualização: indisponível';let src=document.getElementById('windSource');if(src)src.textContent='Fonte: cache local / consulte REDEMET ou WAFS para dado atual'}}
