const FLIGHT_SCENARIOS=[
 {name:'Deterioração meteorológica',prompt:'Durante um treino VFR, as referências à frente ficam progressivamente piores e a margem visual diminui.',choices:['Reconhecer cedo a deterioração e considerar desvio/retorno conforme briefing e condições','Prosseguir até perder todas as referências','Descer automaticamente','Ignorar porque o destino está próximo'],correct:0,debrief:'Boa tomada de decisão VFR começa antes de a situação se tornar crítica. O módulo não decide por si; treina gatilhos e alternativas.'},
 {name:'Vento cruzado',prompt:'O vento observado está aumentando e aproxima-se do limite pessoal definido para treino.',choices:['Reavaliar a operação usando limites pessoais, POH, pista e condições atuais','Usar somente a componente de proa','Ignorar rajadas','Aumentar o peso para compensar'],correct:0,debrief:'Limites pessoais devem funcionar como gatilhos de reavaliação, nunca como substitutos dos limites da aeronave/regulamento.'},
 {name:'Referência perdida',prompt:'Um checkpoint esperado não aparece no tempo previsto.',choices:['Reconhecer a discrepância, manter controle, confirmar posição com múltiplos recursos e gerir combustível','Inventar uma nova posição','Descer abaixo da altitude planejada sem análise','Continuar por memória'],correct:0,debrief:'A disciplina de navegação inclui detectar cedo quando a realidade não corresponde ao plano.'},
 {name:'Pane elétrica noturna',prompt:'Em cenário didático noturno, parte da iluminação/equipamentos elétricos falha.',choices:['Aplicar prioridades e checklist da aeronave, preservar controle e avaliar opções seguras','Desligar toda iluminação sem motivo','Continuar como se nada tivesse ocorrido','Usar o ILS sem habilitação como solução automática'],correct:0,debrief:'O treino integra pane, iluminação, alternativas e limites de habilitação.'},
 {name:'Circuito e tráfego',prompt:'Ao chegar a um aeródromo com tráfego, há dúvida sobre a posição de outra aeronave.',choices:['Aumentar consciência situacional, comunicar/observar e evitar conflito antes de continuar a manobra','Assumir que a outra aeronave o viu','Acelerar a aproximação','Desligar rádio'],correct:0,debrief:'Prevenção de colisões e consciência situacional têm prioridade.'}
];
let flightCurrent=0;
function renderFlightTrainer(){flightScenario()}
function flightScenario(){flightCurrent=Math.floor(Math.random()*FLIGHT_SCENARIOS.length);let s=FLIGHT_SCENARIOS[flightCurrent],e=document.getElementById('flightScenario');if(!e)return;e.innerHTML=`<div class="eyebrow">MISSÃO C152/C172 • ${s.name}</div><h3>${s.prompt}</h3>`+s.choices.map((x,i)=>`<button class="option" data-flight-choice="${i}">${String.fromCharCode(65+i)}. ${x}</button>`).join('');document.getElementById('flightDebrief').classList.add('hide')}
function flightDecision(){let idx=Number(document.querySelector('[data-flight-choice].selected')?.dataset.flightChoice);if(!Number.isInteger(idx))return alert('Selecione uma decisão primeiro.');let s=FLIGHT_SCENARIOS[flightCurrent],ok=idx===s.correct;state.trainer.history.push({scenario:s.name,choice:idx,ok,at:new Date().toISOString()});save();let d=document.getElementById('flightDebrief');d.innerHTML=`<b>${ok?'✓ Boa decisão no cenário':'⚠ Rever decisão'}</b><br>${s.debrief}`;d.className='notice '+(ok?'ok':'');}

const INVA_BANK=[
 {q:'Explique a diferença entre radial VOR e curso.',keys:['radial','estação','curso','direção'],model:'Radial é uma direção magnética que parte do VOR; curso é a direção selecionada/voada e pode ser para ou a partir do auxílio.'},
 {q:'O que você verificaria antes de iniciar um voo VFR de navegação?',keys:['meteorologia','notam','combustível','carta','peso','balanceamento'],model:'Espera-se uma resposta estruturada incluindo meteorologia, NOTAM, cartas/rota, combustível, peso e balanceamento, performance, alternativos e requisitos aplicáveis.'},
 {q:'Por que QDM e QDR não devem ser confundidos?',keys:['qdm','estação','qdr','afasta'],model:'QDM é direção/rumo magnético para a estação; QDR é o recíproco de afastamento.'},
 {q:'Se a meteorologia deteriorar antes do seu limite pessoal, o que muda no seu plano?',keys:['reavaliar','alternativo','desvio','retorno'],model:'O ponto principal é reconhecer o gatilho e reavaliar cedo alternativas como desvio, retorno ou adiamento, sem automatizar uma decisão operacional.'},
 {q:'Explique por que peso e balanceamento deve usar dados da aeronave específica.',keys:['peso vazio','momento','cg','poh'],model:'Peso vazio, braço/momento e equipamentos variam por aeronave; o cálculo operacional deve usar dados atuais da aeronave e limites do POH/AFM.'}
];
let invaCurrent=0;
function renderInva(){if(!document.getElementById('invaQuestionText').textContent.trim())invaQuestion()}
function invaQuestion(){invaCurrent=Math.floor(Math.random()*INVA_BANK.length);document.getElementById('invaQuestionText').textContent=INVA_BANK[invaCurrent].q;document.getElementById('invaAnswer').value='';document.getElementById('invaResult').classList.add('hide')}
function evaluateInva(){let a=(document.getElementById('invaAnswer').value||'').toLowerCase(),q=INVA_BANK[invaCurrent],hits=q.keys.filter(k=>a.includes(k)).length,score=Math.round(100*hits/q.keys.length);state.inva.history.push({q:q.q,score,at:new Date().toISOString()});save();let r=document.getElementById('invaResult');r.innerHTML=`<b>Avaliação didática local: ${score}% de conceitos-chave detectados</b><br>${q.model}<br><small>Esta pontuação é heurística e não equivale à avaliação de um INVA real nem à IA online.</small>`;r.classList.remove('hide')}
function startVoice(){let SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){document.getElementById('invaResult').textContent='Reconhecimento de voz não disponível neste navegador. Use a resposta escrita.';document.getElementById('invaResult').classList.remove('hide');return}let r=new SR();r.lang='pt-BR';r.interimResults=false;r.onresult=e=>{document.getElementById('invaAnswer').value=e.results[0][0].transcript};r.onerror=e=>{document.getElementById('invaResult').textContent='Voz indisponível: '+e.error;document.getElementById('invaResult').classList.remove('hide')};r.start()}



const ATC_SCENARIOS=[
 {p:'Solo informa: “PR-ABC, táxi via Alfa, mantenha antes da pista 09.” Faça um readback didático.',keys:['pr-abc','alfa','pista 09'],model:'O treino espera identificação da aeronave, rota de táxi relevante e restrição de manter antes da pista.'},
 {p:'Torre autoriza alinhamento e espera na pista 09. Quais elementos essenciais você repetiria?',keys:['pista 09','alinhar','aguardar'],model:'O objetivo é reconhecer pista e natureza da autorização/restrição no readback.'},
 {p:'APP fornece QNH 1016 e solicita manter 3500 pés. Faça um readback didático.',keys:['1016','3500'],model:'O treino procura a confirmação do ajuste informado e da altitude atribuída.'},
 {p:'Você não compreendeu uma instrução ATC. O que deve fazer no treino?',keys:['repetir','confirme'],model:'O comportamento treinado é pedir repetição/confirmar o que não foi compreendido, em vez de adivinhar.'},
 {p:'Durante a escuta, seu indicativo é chamado junto com uma alteração de pista. O que deve priorizar na resposta?',keys:['indicativo','pista'],model:'Identifique que a mensagem é para sua aeronave e confirme o elemento operacional relevante, neste caso a pista.'}
];
let atcCurrent=0;
function renderAtc(){if(!document.getElementById('atcPrompt').textContent||document.getElementById('atcPrompt').textContent.includes('Carregando'))atcScenario()}
function atcScenario(){atcCurrent=Math.floor(Math.random()*ATC_SCENARIOS.length);let q=ATC_SCENARIOS[atcCurrent];document.getElementById('atcPrompt').textContent=q.p;document.getElementById('atcAnswer').value='';document.getElementById('atcResult').classList.add('hide')}
function atcEvaluate(){let q=ATC_SCENARIOS[atcCurrent],a=(document.getElementById('atcAnswer').value||'').toLowerCase(),hits=q.keys.filter(k=>a.includes(k)).length,pct=Math.round(100*hits/q.keys.length);state.atc.history.push({scenario:atcCurrent,score:pct,at:new Date().toISOString()});save();let e=document.getElementById('atcResult');e.innerHTML=`<b>${pct}% dos conceitos-chave detectados</b><br>${q.model}<br><small>Avaliação heurística local; não é validação oficial de fraseologia.</small>`;e.classList.remove('hide')}
function atcVoice(){let SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){let e=document.getElementById('atcResult');e.textContent='Reconhecimento de voz não disponível neste navegador. Use texto.';e.classList.remove('hide');return}let r=new SR();r.lang='pt-BR';r.interimResults=false;r.onresult=e=>document.getElementById('atcAnswer').value=e.results[0][0].transcript;r.onerror=e=>{let x=document.getElementById('atcResult');x.textContent='Voz indisponível: '+e.error;x.classList.remove('hide')};r.start()}

const EMERGENCY_SCENARIOS=[
 {p:'Em cruzeiro didático, ocorre perda parcial de potência e a aeronave ainda é controlável.',a:['Manter controle, analisar opções, aplicar checklist/procedimento da aeronave e preparar alternativa segura','Fixar-se apenas no rádio','Continuar sem avaliar','Descer imediatamente sem considerar terreno'],c:0,d:'O módulo treina prioridades: controle da aeronave, diagnóstico/checklist aplicável e opções seguras.'},
 {p:'A indicação elétrica mostra possível falha do sistema de carga.',a:['Confirmar a anomalia, gerir carga conforme checklist e planejar uma conclusão segura do voo','Ligar todos os equipamentos','Ignorar até a bateria acabar','Desligar o motor'],c:0,d:'Uma falha elétrica exige gestão disciplinada de energia e uso do procedimento específico da aeronave.'},
 {p:'A meteorologia à frente deteriora e a margem visual está diminuindo.',a:['Reconhecer cedo a tendência e reavaliar retorno/desvio/alternativa antes de perder margem','Prosseguir até entrar em nuvem','Descer para manter o solo à vista sem avaliar terreno','Aumentar velocidade'],c:0,d:'ADM eficaz reconhece a deterioração cedo e preserva alternativas.'},
 {p:'O combustível remanescente está abaixo do previsto no checkpoint.',a:['Recalcular autonomia, comparar alternativas e tratar a discrepância antes que vire urgência','Ignorar porque o indicador pode estar errado','Aumentar potência','Cancelar o NavLog'],c:0,d:'Uma discrepância de combustível deve ser reconhecida e gerida cedo com dados e alternativas.'},
 {p:'Você não consegue confirmar sua posição por uma referência visual esperada.',a:['Manter controle, admitir a incerteza, usar múltiplos recursos e evitar continuar com posição inventada','Escolher uma cidade qualquer','Descer sem análise','Continuar por memória'],c:0,d:'O treino reforça consciência da incerteza e recuperação sistemática da navegação.'},
 {p:'Há dúvida sobre a posição de outro tráfego no circuito.',a:['Aumentar separação/consciência situacional e esclarecer antes de prosseguir a manobra','Assumir que ele o viu','Acelerar para pousar primeiro','Parar de transmitir'],c:0,d:'Prevenção de conflito e consciência situacional têm prioridade.'}
];
let emergencyCurrent=0;
function renderEmergency(){emergencyScenario()}
function emergencyScenario(){emergencyCurrent=Math.floor(Math.random()*EMERGENCY_SCENARIOS.length);let s=EMERGENCY_SCENARIOS[emergencyCurrent];document.getElementById('emPrompt').textContent=s.p;document.getElementById('emChoices').innerHTML=s.a.map((x,i)=>`<button class="option" data-emergency-choice="${i}">${String.fromCharCode(65+i)}. ${x}</button>`).join('');document.getElementById('emResult').classList.add('hide')}
function emergencyEvaluate(){let sel=document.querySelector('[data-emergency-choice].selected');if(!sel)return alert('Selecione uma decisão.');let idx=+sel.dataset.emergencyChoice,s=EMERGENCY_SCENARIOS[emergencyCurrent],ok=idx===s.c;state.emergency.history.push({scenario:emergencyCurrent,choice:idx,ok,at:new Date().toISOString()});save();let e=document.getElementById('emResult');e.innerHTML=`<b>${ok?'✓ Decisão coerente com o objetivo didático':'⚠ Rever o raciocínio'}</b><br>${s.d}`;e.className='notice '+(ok?'ok':'')}

async function renderLibrary(){let local=document.getElementById('libraryLocal'),src=document.getElementById('librarySources');if(!local||!src)return;let mats=await getAllMaterials();local.innerHTML=mats.length?mats.map(m=>`<div class="row"><div class="grow"><b>${m.name}</b><small>${Math.round((m.size||0)/1024)} KB • ${new Date(m.addedAt).toLocaleDateString('pt-PT')}</small></div><button class="btn small secondary" data-remove-material="${m.id}">REMOVER</button></div>`).join(''):'<div class="notice">Nenhum material adicional guardado neste dispositivo.</div>';src.innerHTML=Object.entries(SOURCE_COVERAGE).map(([k,v])=>`<div class="row"><div class="grow"><b>${k} — ${SUBJECTS[k]}</b><small>Capítulos com fonte identificada: ${(v.verified||[]).join(', ')||'—'}</small></div><span class="pill">${(v.verified||[]).length}</span></div>`).join('')}
async function removeMaterial(id){try{let db=await openDB(),tx=db.transaction('materials','readwrite');tx.objectStore('materials').delete(id);await new Promise((r,j)=>{tx.oncomplete=r;tx.onerror=()=>j(tx.error)});renderLibrary()}catch(e){alert('Não foi possível remover: '+e.message)}}
function renderSettings(){let ui=state.settings.ui||{fontScale:1,displayName:PROFILE_NAME};document.getElementById('fontScale').value=String(ui.fontScale||1);document.getElementById('displayName').value=ui.displayName||PROFILE_NAME;document.documentElement.style.fontSize=(16*(ui.fontScale||1))+'px'}
function saveSettings(){let scale=+document.getElementById('fontScale').value||1,name=(document.getElementById('displayName').value||PROFILE_NAME).trim().slice(0,30);state.settings.ui={fontScale:scale,displayName:name};save();document.documentElement.style.fontSize=(16*scale)+'px';renderHome();let e=document.getElementById('settingsMsg');e.textContent='Preferências guardadas neste dispositivo.';e.classList.remove('hide')}
function printBriefing(){window.print()}

function renderCompetency(){let e=document.getElementById('competencyMap');if(!e)return;let rows={};(state.answers||[]).forEach(a=>{let k=(a.subject||'Geral')+' • '+(a.topic||a.chapter||'Geral');if(!rows[k])rows[k]={n:0,ok:0};rows[k].n++;if(a.correct||a.ok)rows[k].ok++});let keys=Object.keys(rows);if(!keys.length){e.innerHTML='<div class="notice">Ainda não há respostas suficientes. O mapa será preenchido conforme você treina.</div>';return}e.innerHTML=keys.sort().map(k=>{let r=rows[k],pct=Math.round(100*r.ok/r.n),cls=pct>=95?'ok':'';return `<div class="notice ${cls}"><b>${k}</b> — ${pct}% (${r.ok}/${r.n}) ${pct<95?'• RECUPERAÇÃO NECESSÁRIA':'• DOMINADO'}</div>`}).join('')}
function renderNavlog(){let r=document.getElementById('navlogResult');if(r)r.classList.add('hide')}
function norm360(x){return ((x%360)+360)%360}
function calcNavlog(){let n=id=>Number(document.getElementById(id)?.value),d=n('nlDist'),tas=n('nlTas'),tc=n('nlCourse'),wd=n('nlWindDir'),ws=n('nlWindSpd'),burn=n('nlBurn'),r=document.getElementById('navlogResult');if(!(d>0&&tas>0&&burn>=0&&ws>=0)){r.textContent='Revise os valores.';r.classList.remove('hide');return}let rel=(wd-tc)*Math.PI/180;let ratio=Math.max(-.999,Math.min(.999,(ws/tas)*Math.sin(rel)));let wca=Math.asin(ratio)*180/Math.PI;let hdg=norm360(tc+wca);let gs=tas*Math.cos(wca*Math.PI/180)-ws*Math.cos(rel);if(gs<=0){r.textContent='Condição sem solução útil neste modelo didático (GS ≤ 0).';r.classList.remove('hide');return}let hours=d/gs,fuel=hours*burn;r.innerHTML=`<b>Resultado didático</b><br>WCA: ${wca.toFixed(1)}° • Proa verdadeira estimada: ${hdg.toFixed(1)}° • GS: ${gs.toFixed(1)} kt • EET: ${Math.floor(hours)}h ${Math.round((hours%1)*60)}min • Combustível em rota: ${fuel.toFixed(1)} gal<br><small>Não inclui reserva, táxi, subida/descida, declinação magnética ou correções específicas do POH.</small>`;r.classList.remove('hide')}

function selfTest(){let tests=diagnosticResults().map(x=>[x.name,x.ok,x.detail||'']);document.getElementById('selftest').textContent='SELFTEST:'+JSON.stringify(tests);document.body.dataset.selftest=tests.every(x=>x[1])?'PASS':'FAIL'}
function init(){renderProfileUI();renderBookStats();document.documentElement.style.fontSize=(16*((state.settings.ui&&state.settings.ui.fontScale)||1))+'px';renderHome();renderSubjects();renderProgress();renderAI();renderVideos();renderPlanner();net();bind();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(console.warn);if(new URLSearchParams(location.search).has('selftest'))selfTest()}
document.addEventListener('DOMContentLoaded',init);
